-- Textos y exclusiones de la reactivación del 20/11/2026.
-- No es una migración de esquema: se aplica una vez sobre reactivation_message_overrides.

on conflict (phone_key) do update set
  template_name = excluded.template_name,
  var1 = excluded.var1,
  var2 = excluded.var2,
  exclude = excluded.exclude,
  hold_reason = excluded.hold_reason,
  handler = excluded.handler,
  note = excluded.note,
  updated_by = excluded.updated_by,
  updated_at = now();
